/* Original lantern-and-stair discovery world. No timers, autoplay audio, or canvas frame loop. */
const QuizWorld={chapters:[['THE SPARK','Notice what draws you in.'],['THE PULL','Follow your own curiosity.'],['THE CLIMB','See what feels like you.'],['THE HORIZON','Your next direction is taking shape.']],themes:{build:['#a4efda','Make an idea real.'],logic:['#92d7eb','Find the pattern.'],people:['#f1b7cf','Start with understanding.'],create:['#c7a3f2','Imagine another way.'],lead:['#f1d195','Bring people forward.'],research:['#aabcf6','Ask the next question.']}};
function quizStairWorld(progress=0,chapter=0,step=1){const steps=Array.from({length:13},(_,i)=>{const x=182+i*15,y=316-i*15;return `<g class="quiz-stone ${i<=progress?'lit':''}" style="--stone:${i}"><path d="M${x} ${y}l50-22 54 22-50 22Z"/><path d="M${x} ${y}l54 22v13l-54-22Z"/><path d="M${x+54} ${y+22}l50-22v13l-50 22Z"/></g>`}).join('');return `<div class="quiz-world" data-quiz-world data-chapter="${chapter}" style="--climb-offset:${step*15}px" aria-hidden="true"><div class="quiz-world-halo"></div><svg viewBox="0 0 680 460" class="quiz-world-drawing"><defs><linearGradient id="quiz-arch" x2="1" y2="1"><stop stop-color="#a5b3d9" stop-opacity=".32"/><stop offset="1" stop-color="#6c4c91" stop-opacity=".06"/></linearGradient><linearGradient id="quiz-path" x2="1" y2="0"><stop stop-color="#a4efda"/><stop offset="1" stop-color="#d2b4ff"/></linearGradient><radialGradient id="quiz-lantern"><stop stop-color="#fff1cd"/><stop offset=".2" stop-color="#a4efda" stop-opacity=".7"/><stop offset="1" stop-color="#a4efda" stop-opacity="0"/></radialGradient></defs><g class="quiz-arches"><path d="M77 411V171Q77 41 211 41H468Q601 41 601 171V411"/><path d="M97 407V175Q97 61 211 61H468Q581 61 581 175V407"/><path d="M116 402V184Q116 83 218 83H461Q562 83 562 184V402"/></g><g class="quiz-shelves"><path d="M79 217h73v166H79m22-143v46m18-46v46m16-46v46m-56 9h73m-51 17v51m18-51v51m16-51v51M528 217h73m-73 78h73m-50-55v46m19-46v46m16-46v46m-35 27v50m19-50v50m16-50v50"/></g><g class="quiz-horizon"><circle cx="429" cy="103" r="34"/><path d="M370 150h120m-104 11h88m-69 11h50"/></g><path class="quiz-far-route" d="M252 374L471 153"/>${steps}<g class="quiz-traveler" style="--traveler-x:${218+progress*15}px;--traveler-y:${318-progress*15}px"><ellipse class="traveler-shadow" cx="0" cy="0" rx="13" ry="5"/><path class="traveler-body" d="M-8-2l2-19h12l6 19Z"/><circle class="traveler-head" cx="0" cy="-29" r="6"/><path class="traveler-arm" d="M5-16l12-6"/><path d="M17-24v-8h9v13h-9Z" fill="#d4f2d5"/><circle class="lantern-glow" cx="21" cy="-24" r="32" fill="url(#quiz-lantern)"/></g><g class="quiz-world-motes">${Array.from({length:13},(_,i)=>`<circle cx="${121+(i*53)%429}" cy="${91+(i*41)%227}" r="${i%3===0?2:1}" style="--mote:${i}"/>`).join('')}</g><path class="quiz-choice-ray" d="M260 338Q345 242 439 109"/></svg><span class="quiz-world-label">A little closer to your direction.</span></div>`}
function immersiveQuestion(){if(!answers.length&&quizIndex===0)restoreQuiz();if(quizIndex>=quizLength)quizIndex=quizLength-1;const q=ProductCore.questions[quizIndex],chapter=Math.min(3,Math.floor(quizIndex/quizLength*4)),progress=quizIndex/quizLength*12;journeyLastQuizIndex=quizIndex;return `<section class="quiz journey-quiz immersive-quiz" data-quiz-chapter="${chapter}"><div class="quiz-sky" aria-hidden="true"></div><div class="quiz-content"><div class="quiz-topline"><a class="journey-secondary" href="#discover">← Save & leave</a><span>${quizIndex+1} / ${quizLength}</span><button class="motion-control" data-toggle-motion>${journeyReduced()?'Motion off':'Motion on'}</button></div><div class="quiz-chapter-rail" aria-label="Discovery chapters">${QuizWorld.chapters.map(([label],i)=>`<span class="${i===chapter?'current':i<chapter?'passed':''}" ${i===chapter?'aria-current="step"':''}><i></i>${label.replace('THE ','')}</span>`).join('')}</div><div class="immersive-layout"><div class="quiz-art-column">${quizStairWorld(progress,chapter,12/quizLength)}<div class="quiz-whisper" aria-hidden="true"><span class="quiz-whisper-symbol">✦</span><span id="quiz-hover-whisper">${QuizWorld.chapters[chapter][1]}</span></div></div><div class="quiz-question-column"><div class="quiz-chapter-caption"><span class="eyebrow">0${chapter+1} / ${QuizWorld.chapters[chapter][0]}</span><span class="quiz-question-hint">No right answer. Just your answer.</span></div><h1 id="quiz-prompt" tabindex="-1">${esc(q.prompt)}</h1><div class="choices immersive-choices">${q.choices.map((label,i)=>`<button class="choice journey-answer ${answers[quizIndex]===q.tags[i]?'selected':''}" data-product-answer="${q.tags[i]}" aria-pressed="${answers[quizIndex]===q.tags[i]}"><span class="answer-illustration">${journeyIcon(q.tags[i])}</span><span class="answer-number">0${i+1}</span><span class="choice-copy">${esc(label)}</span><span class="answer-check" aria-hidden="true">↗</span></button>`).join('')}</div><div class="quiz-bottomline"><button class="journey-secondary" id="product-quiz-back" ${quizIndex===0?'disabled':''}>← Previous</button><span class="quiet-note">Tap a path · or press 1–4</span></div></div></div><div class="journey-quiz-trail immersive-trail" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${quizLength}" aria-valuenow="${quizIndex}" style="--progress:${quizIndex/quizLength}"><div></div><span aria-hidden="true">✦</span></div><details class="journey-footnote"><summary>About your discovery</summary><p>Your interests guide these exploratory recommendations. This is not a validated personality test or admission prediction. No time limit, sound or speed scoring. Save and leave whenever you like.</p></details></div></section>`}
function bindImmersive(){const quiz=document.querySelector('.immersive-quiz'),world=quiz?.querySelector('[data-quiz-world]');if(!quiz||!world)return;const setTheme=el=>{const [color,whisper]=QuizWorld.themes[el.dataset.productAnswer]||QuizWorld.themes.build;quiz.style.setProperty('--quiz-choice-color',color);quiz.dataset.hoverTheme=el.dataset.productAnswer;quiz.querySelector('#quiz-hover-whisper').textContent=whisper};quiz.querySelectorAll('[data-product-answer]').forEach(el=>{el.onpointerenter=()=>setTheme(el);el.onfocus=()=>setTheme(el);el.addEventListener('click',()=>{world.classList.add('quiz-step-chosen')},{capture:true});el.onpointermove=e=>{if(journeyReduced()||e.pointerType==='touch')return;const r=el.getBoundingClientRect();el.style.setProperty('--choice-x',Math.max(-1,Math.min(1,(e.clientX-r.left)/Math.max(1,r.width)-.5))*2+'');el.style.setProperty('--choice-y',Math.max(-1,Math.min(1,(e.clientY-r.top)/Math.max(1,r.height)-.5))*2+'')};el.onpointerleave=()=>{el.style.setProperty('--choice-x','0');el.style.setProperty('--choice-y','0')}});world.onpointermove=e=>{if(journeyReduced()||e.pointerType==='touch')return;const r=world.getBoundingClientRect();world.style.setProperty('--world-turn',((e.clientX-r.left)/Math.max(1,r.width)-.5)*4+'deg')};world.onpointerleave=()=>world.style.setProperty('--world-turn','0deg')}
function installImmersiveQuiz(){question=immersiveQuestion;const discoverBefore=discover;discover=()=>discoverBefore().replace('<div class="discovery-invite">',`<div class="discovery-invite discovery-world-invite">${quizStairWorld(0,0)}<div class="quiz-invitation-copy"><span class="eyebrow">FOLLOW YOUR CURIOSITY</span>`).replace('</div><a class="journey-secondary" href="#profile">','</div></div><a class="journey-secondary" href="#profile">');const resultsBefore=results;results=()=>{const content=resultsBefore();return state.results?.length?content.replace('<div class="grid journey-paths">','<p class="quiz-reveal-caption"><span aria-hidden="true">✦</span> Every small choice brought you here.</p><div class="grid journey-paths">'):content};const bindBefore=bind;bind=()=>{bindBefore();bindImmersive()}}
